# Real-world example: Text formatting
print("\n\n📝 Another Example - Text Formatting:")

class TextComponent(ABC):
    @abstractmethod
    def render(self) -> str:
        pass

class PlainText(TextComponent):
    def __init__(self, text):
        self.text = text

    def render(self) -> str:
        return self.text

class TextDecorator(TextComponent):
    def __init__(self, component: TextComponent):
        self._component = component

    def render(self) -> str:
        return self._component.render()

class BoldDecorator(TextDecorator):
    def render(self) -> str:
        return f"**{self._component.render()}**"

class ItalicDecorator(TextDecorator):
    def render(self) -> str:
        return f"_{self._component.render()}_"
