```python
class Memory:
    def load(self, position, data):
        print(f"   🧠 Memory: Loading data '{data}' at position {position}")

class HardDrive:
    def read(self, sector, size):
        print(f"   💾 HardDrive: Reading {size} bytes from sector {sector}")
        return "boot_data"

class GPU:
    def render(self):
        print("   🎮 GPU: Rendering graphics...")

# Facade
class ComputerFacade:
    """Simplified interface to boot a computer"""
    def __init__(self):
        self.cpu = CPU()
        self.memory = Memory()
        self.hard_drive = HardDrive()
        self.gpu = GPU()

    def start(self):
        """Simple method that hides complex boot process"""
        print("\n🚀 Starting computer...")
        self.cpu.freeze()
        boot_data = self.hard_drive.read(0, 1024)
        self.memory.load(0, boot_data)
        self.cpu.jump(0)
        self.cpu.execute()
        self.gpu.render()
        print("✅ Computer started successfully!\n")

# Demo
print("\n🔍 Testing Facade Pattern:")
computer = ComputerFacade()
computer.start()  # Simple call, complex operations hidden!

