# Real subject - expensive to create
class RealImage(Image):
    def __init__(self, filename):
        self.filename = filename
        self._load_from_disk()

    def _load_from_disk(self):
        print(f"   💾 Loading image from disk: {self.filename}")
        time.sleep(1)  # Simulate expensive operation
        print(f"   ✅ Image loaded: {self.filename}")

    def display(self):
        print(f"   🖼️  Displaying: {self.filename}")

# Proxy - delays expensive creation
class ImageProxy(Image):
    def __init__(self, filename):
        self.filename = filename
        self._real_image = None

    def display(self):
        if self._real_image is None:
            print("   🔄 Creating real image...")
            self._real_image = RealImage(self.filename)
        self._real_image.display()

# Demo
print("\n🔍 Testing Proxy Pattern (Virtual Proxy):")
print("\n1. Creating image proxies (fast):")
images = [
    ImageProxy("photo1.jpg"),
    ImageProxy("photo2.jpg"),
    ImageProxy("photo3.jpg")
]
print("✅ All proxies created instantly!")

print("\n2. Displaying images (loads on demand):")
for i, img in enumerate(images, 1):
    print(f"\nImage {i}:")
    img.display()

print("\n3. Displaying again (uses cached):")
images[0].display()

