# Observer interface
class Observer(ABC):
    @abstractmethod
    def update(self, subject):
        pass

# Subject (Observable)
class Subject:
    def __init__(self):
        self._observers: List[Observer] = []
        self._state = None

    def attach(self, observer: Observer):
        print(f"   ➕ Attached: {observer.__class__.__name__}")
        self._observers.append(observer)

    def detach(self, observer: Observer):
        print(f"   ➖ Detached: {observer.__class__.__name__}")
        self._observers.remove(observer)

    def notify(self):
        print(f"   📢 Notifying {len(self._observers)} observers...")
        for observer in self._observers:
            observer.update(self)

    def set_state(self, state):
        print(f"\n🔄 Subject state changed to: {state}")
        self._state = state
        self.notify()

    def get_state(self):
        return self._state

# Concrete observers
class EmailObserver(Observer):
    def update(self, subject):
        print(f"   📧 EmailObserver: Sending email about '{subject.get_state()}'")

class SMSObserver(Observer):
    def update(self, subject):
        print(f"   📱 SMSObserver: Sending SMS about '{subject.get_state()}'")
